/**
 * The Agent Client Protocol (ACP) messages Nexus accepts and sends: a SUBSET of ACP version 1, plus Nexus's own
 * extension methods and `_meta` members. `AcpAdapterDocument` is the published contract
 * (docs/protocol/acp-adapter-v<N>.schema.json, generated by cli/scripts/gen_acp_schema.mjs); a change to a type here
 * changes that schema and needs a ledger entry in docs/protocol/ACP_ADAPTER_VERSIONS.json.
 *
 * Protocol facts are cited as "published specification, <page>" (agentclientprotocol.com protocol pages, checked
 * 2026-11-22). Facts that could not be checked are gathered in the one block marked NOT VERIFIED below.
 *
 * This module is pure: constants and types only, no I/O, no value import from outside cli/src/acp.
 */
import type { EngineeringOutcome, ExecutionState, TurnReason, VerificationStatus } from "../core/turn.js";
import type { ReceiptSection } from "../evidence.js";
import type { VerifyJsonResult } from "../verify_contract.js";

/** Version of the published schema of this adapter's messages (the ledger key `schema_version`). */
export const ACP_ADAPTER_SCHEMA_VERSION = 4;

/**
 * The ACP protocol version Nexus speaks: an integer major version, currently 1 (published specification,
 * initialization). An agent that supports the requested version answers with it; otherwise it answers with the latest
 * version it supports. Nexus supports exactly this one, so the answer is always this value.
 */
export const ACP_PROTOCOL_VERSION = 1;

export const JSONRPC_VERSION = "2.0";

/**
 * JSON-RPC error codes Nexus sends. -32601, -32602, -32000 (authentication required) and -32800 (request cancelled,
 * for a request ended by `$/cancel_request`) appear verbatim in the published specification; -32700, -32600 and -32603
 * are the standard JSON-RPC codes (specification schema page, read as a summary). -32002 exists in the specification
 * for `session/close` and is not used here.
 */
export const ACP_ERROR = {
  PARSE_ERROR: -32700,
  INVALID_REQUEST: -32600,
  METHOD_NOT_FOUND: -32601,
  INVALID_PARAMS: -32602,
  INTERNAL_ERROR: -32603,
  AUTH_REQUIRED: -32000,
  REQUEST_CANCELLED: -32800,
} as const;
export type AcpErrorCode = (typeof ACP_ERROR)[keyof typeof ACP_ERROR];

/**
 * Extension names. The specification reserves every method name that starts with an underscore for custom extensions
 * and lets `_meta` carry custom data (published specification, extensibility). It RECOMMENDS a reverse-DNS prefix of a
 * domain the implementer controls (`_com.example/...`, `com.example/<name>`). Nexus uses the short prefix `nexus`:
 * OPEN OWNER DECISION, whether to move to a reverse-DNS prefix before the experimental mark is removed. Every extension
 * name is declared here and nowhere else (a test checks each against the two prefixes), so that decision is one edit.
 * The `_meta` root keys `traceparent`, `tracestate` and `baggage` are reserved for W3C trace context and never used.
 */
export const ACP_EXTENSION_METHOD_PREFIX = "_nexus/";
export const ACP_META_PREFIX = "nexus/";
/** Read the receipt of a turn or verification. */
export const ACP_RECEIPT_GET_METHOD = "_nexus/receipt/get";
/** Request verification of an active session's workspace. */
export const ACP_VERIFY_METHOD = "_nexus/verify";
export const ACP_META_VERIFICATION = "nexus/verification";
export const ACP_META_POSTURE = "nexus/posture";
export const ACP_META_HISTORY = "nexus/history";
export const ACP_META_MCP_SERVERS_IGNORED = "nexus/mcp_servers_ignored";
export const ACP_META_APPROVAL_DIGEST = "nexus/approval_digest";
export const ACP_META_DIFF = "nexus/diff";
export const ACP_META_EXPERIMENTAL = "nexus/experimental";
export const ACP_META_EXTENSIONS = "nexus/extensions";
export const ACP_META_SIDECAR_PROTOCOL = "nexus/sidecar_protocol";

/**
 * The session update that carries the verification object: `session_info_update` is a session update kind of the
 * specification (published specification, prompt-turn / schema) and `_meta` is allowed on session update payloads.
 */
export const ACP_VERIFICATION_CARRIER = "session_info_update";

/** Protocol-level cancellation of one request by id; the cancelled request is answered with -32800 (published specification, schema). */
export const ACP_CANCEL_REQUEST_METHOD = "$/cancel_request";

/**
 * DECLARED DEVIATIONS from the published specification (docs/ACP.md states them):
 *
 * `ACP_DEVIATION_NO_CLIENT_MCP_SERVERS`: "All Agents MUST support the stdio transport [for MCP servers], while HTTP
 * and SSE transports are optional" (session-setup). Nexus v1.3.0 connects no client-supplied MCP server at all: which
 * servers load is decided by the operator's allowlist and workspace trust, not by the client. A non-empty `mcpServers`
 * is reported in `_meta["nexus/mcp_servers_ignored"]`.
 *
 */
export const ACP_DEVIATION_NO_CLIENT_MCP_SERVERS = "client-supplied MCP servers are not connected (stdio included)";

/** The only two answers Nexus offers to a permission request. `allow_always` and `reject_always` exist in the specification and are never offered. */
export const ACP_ALLOW_ONCE_OPTION_ID = "allow_once";
export const ACP_REJECT_ONCE_OPTION_ID = "reject_once";

/**
 * Limits on untrusted input. The specification sets no message size limit and no batch rule (published
 * specification, transports), so every number here, and the refusal of a batch, is Nexus's own choice.
 */
export const ACP_MAX_LINE_BYTES = 4 * 1024 * 1024;
/** Inbound lines over the cap after which the adapter closes the connection. */
export const ACP_MAX_OVERSIZED_LINES = 3;
/** A sidecar child's line over this marks its session failed. */
export const ACP_MAX_CHILD_LINE_BYTES = 16 * 1024 * 1024;
export const ACP_MAX_JSON_DEPTH = 64;
export const ACP_MAX_TEXT_BLOCK_CHARS = 256_000;
export const ACP_MAX_PROMPT_CHARS = 1_000_000;
export const ACP_MAX_PROMPT_BLOCKS = 64;
export const ACP_MAX_CWD_CHARS = 4_096;
export const ACP_MAX_SESSION_ID_CHARS = 128;
export const ACP_MAX_URI_CHARS = 2_048;
/** The same limit as the sidecar's `MAX_CLIENT_FIELD`, which receives these fields. */
export const ACP_MAX_CLIENT_FIELD_CHARS = 100;
export const ACP_MAX_MCP_SERVERS_INSPECTED = 32;
export const ACP_MAX_SESSIONS = 4;
export const ACP_MAX_INFLIGHT_REQUESTS = 32;
export const ACP_MAX_PENDING_PERMISSIONS_PER_SESSION = 1;
/** Receipts kept per session for `_nexus/receipt/get`. */
export const ACP_RECEIPT_STORE_SIZE = 32;
/** Settled or abandoned agent-to-client request ids remembered, so a late reply is told apart from an unknown one. */
export const ACP_TOMBSTONE_COUNT = 256;
/** Seconds without an answer to a permission request before it is denied (`--permission-timeout`). */
export const ACP_PERMISSION_TIMEOUT_SECS = 600;
/** Longest string id of a request, method name and receipt id accepted. */
export const ACP_MAX_REQUEST_ID_CHARS = 256;
export const ACP_MAX_METHOD_CHARS = 128;
export const ACP_MAX_RECEIPT_ID_CHARS = 256;
/** Characters of text in one tool-call content block, and diff blocks in one update. */
export const ACP_MAX_TOOL_TEXT_CHARS = 8_000;
export const ACP_MAX_DIFF_BLOCKS = 64;
/** Characters of a failed turn's detail carried in an error message. */
export const ACP_MAX_ERROR_MESSAGE_CHARS = 2_000;

// ---------------------------------------------------------------------------------------------------------------------
// Not verified against the published specification as of this slice: see the v1.3 plan's AC-1 review notes.
// Every value below rests on a summary of the specification's schema page or on Nexus's own choice. Correct them here.
// ---------------------------------------------------------------------------------------------------------------------
/** `protocolVersion` range accepted in `initialize`: uint16 per a summary of the schema, not its verbatim text. */
export const ACP_NV_MAX_PROTOCOL_VERSION = 65_535;
/**
 * The exact `RequestId` type is known from a summary only (number, string, and null). Nexus accepts a string or an
 * integer as a request id and refuses null and a fractional number; for its own agent-to-client requests it sends
 * integers only (whether every client accepts string ids is unknown, and integers are accepted by all seen).
 */
export const ACP_NV_REQUEST_ID_KINDS = ["string", "integer"] as const;
/**
 * The code answered to any method sent before `initialize`. The specification states the initialize-first rule only for
 * session creation; refusing every other method is Nexus's choice, and so is the code.
 */
export const ACP_NV_NOT_INITIALIZED_CODE = ACP_ERROR.INVALID_REQUEST;
/** The code answered to a batch (a top-level array). The specification has no batch rule; the refusal is Nexus's choice. */
export const ACP_NV_BATCH_CODE = ACP_ERROR.INVALID_REQUEST;
// Also unverified and therefore not used by any code here: the `fs/*` and `terminal/*` method shapes (Nexus never calls
// them), every numeric limit above (the specification names none), and whether real clients send a non-empty
// `mcpServers` by default.
// ---------------------------------------------------------------------------------------------------------------------
// End of the NOT VERIFIED block.
// ---------------------------------------------------------------------------------------------------------------------

/** A JSON-RPC request id: a string or an integer. */
export type AcpId = string | number;

/** Custom data. Never read for authority: no `_meta` member a client sends changes what a session may do. */
export interface AcpMeta {
  [key: string]: unknown;
}

// ---- Client to agent ------------------------------------------------------------------------------------------------

export interface AcpImplementationInfo {
  name: string;
  title?: string | null;
  version: string;
}

/** `clientCapabilities` is accepted and never consulted: Nexus calls no client method (`fs/*`, `terminal/*`) whatever it says. */
export interface AcpInitializeParams {
  protocolVersion: number;
  clientCapabilities?: AcpMeta;
  clientInfo?: AcpImplementationInfo | null;
  _meta?: AcpMeta;
}

/**
 * `mcpServers` is required by the specification and must be an array; its entries are not connected (see
 * ACP_DEVIATION_NO_CLIENT_MCP_SERVERS). `additionalDirectories` is accepted only when empty, and `systemPrompt` is
 * refused when present: Nexus supports neither.
 */
export interface AcpNewSessionParams {
  cwd: string;
  mcpServers: unknown[];
  /** Accepted only when empty or null. */
  additionalDirectories?: unknown[] | null;
  _meta?: AcpMeta;
}

export interface AcpLoadSessionParams {
  sessionId: string;
  cwd: string;
  mcpServers: unknown[];
  /** Accepted only when empty or null. */
  additionalDirectories?: unknown[] | null;
  _meta?: AcpMeta;
}

export interface AcpTextBlock {
  type: "text";
  text: string;
  annotations?: unknown;
  _meta?: AcpMeta;
}

/** Reduced to one reference line of the prompt; Nexus never reads or fetches the URI. */
export interface AcpResourceLinkBlock {
  type: "resource_link";
  uri: string;
  name?: string;
  title?: string | null;
  description?: string | null;
  mimeType?: string | null;
  size?: number | null;
  annotations?: unknown;
  _meta?: AcpMeta;
}

/** The baseline content blocks (published specification, content). `image`, `audio` and `resource` need capabilities Nexus does not declare, and are refused. */
export type AcpPromptBlock = AcpTextBlock | AcpResourceLinkBlock;

export interface AcpPromptParams {
  sessionId: string;
  prompt: AcpPromptBlock[];
  _meta?: AcpMeta;
}

export interface AcpCancelParams {
  sessionId: string;
  _meta?: AcpMeta;
}

export interface AcpCancelRequestParams {
  requestId: AcpId;
  _meta?: AcpMeta;
}

/** Without `receiptId`: the latest receipt of the session. */
export interface AcpReceiptGetParams {
  sessionId: string;
  receiptId?: string;
  _meta?: AcpMeta;
}

export interface AcpPermissionSelected {
  outcome: "selected";
  optionId: string;
  _meta?: AcpMeta;
}

export interface AcpPermissionCancelled {
  outcome: "cancelled";
  _meta?: AcpMeta;
}

export type AcpPermissionOutcome = AcpPermissionSelected | AcpPermissionCancelled;

/** Only `selected` with the allow-once option id approves; every other result, well-formed or not, denies. */
export interface AcpPermissionResult {
  outcome: AcpPermissionOutcome;
  _meta?: AcpMeta;
}

/** The error member of a response a client sends to an agent request. */
export interface AcpClientError {
  code: number;
  message: string;
  data?: unknown;
}

export interface AcpInitializeRequest {
  jsonrpc: "2.0";
  id: AcpId;
  method: "initialize";
  params: AcpInitializeParams;
}

export interface AcpNewSessionRequest {
  jsonrpc: "2.0";
  id: AcpId;
  method: "session/new";
  params: AcpNewSessionParams;
}

export interface AcpLoadSessionRequest {
  jsonrpc: "2.0";
  id: AcpId;
  method: "session/load";
  params: AcpLoadSessionParams;
}

export interface AcpPromptRequest {
  jsonrpc: "2.0";
  id: AcpId;
  method: "session/prompt";
  params: AcpPromptParams;
}

export interface AcpReceiptGetRequest {
  jsonrpc: "2.0";
  id: AcpId;
  method: typeof ACP_RECEIPT_GET_METHOD;
  params: AcpReceiptGetParams;
}

/** The caller identifies an active session only; all verification authority belongs to the server operator. */
export interface AcpVerifyParams {
  sessionId: string;
  _meta?: AcpMeta;
}

export interface AcpVerifyRequest {
  jsonrpc: "2.0";
  id: AcpId;
  method: typeof ACP_VERIFY_METHOD;
  params: AcpVerifyParams;
}

export interface AcpCancelNotification {
  jsonrpc: "2.0";
  method: "session/cancel";
  params: AcpCancelParams;
}

export interface AcpCancelRequestNotification {
  jsonrpc: "2.0";
  method: typeof ACP_CANCEL_REQUEST_METHOD;
  params: AcpCancelRequestParams;
}

/** The client's answer to `session/request_permission`; `id` is the integer id of that request. */
export interface AcpPermissionResponse {
  jsonrpc: "2.0";
  id: number;
  result: AcpPermissionResult;
}

/** An error answer to `session/request_permission`: a denial. */
export interface AcpPermissionErrorResponse {
  jsonrpc: "2.0";
  id: number;
  error: AcpClientError;
}

/** Everything a client may send that Nexus acts on. Any other method is answered -32601 (a request) or ignored (a notification). */
export type AcpClientMessage =
  | AcpInitializeRequest
  | AcpNewSessionRequest
  | AcpLoadSessionRequest
  | AcpPromptRequest
  | AcpReceiptGetRequest
  | AcpVerifyRequest
  | AcpCancelNotification
  | AcpCancelRequestNotification
  | AcpPermissionResponse
  | AcpPermissionErrorResponse;

// ---- Agent to client ------------------------------------------------------------------------------------------------

export interface AcpAgentCapabilitiesMeta {
  [ACP_META_EXPERIMENTAL]: true;
  [ACP_META_EXTENSIONS]: string[];
  [ACP_META_SIDECAR_PROTOCOL]: number;
}

/** No `sessionCapabilities`: Nexus offers no session list, resume, fork, close or delete. */
export interface AcpAgentCapabilities {
  loadSession: true;
  promptCapabilities: { image: false; audio: false; embeddedContext: false };
  mcpCapabilities: { http: false; sse: false };
  _meta: AcpAgentCapabilitiesMeta;
}

export interface AcpInitializeResult {
  protocolVersion: typeof ACP_PROTOCOL_VERSION;
  agentInfo: { name: "nexus"; title: "Nexus Code"; version: string };
  /** Always empty: Nexus has no authentication method over ACP. */
  authMethods: unknown[];
  agentCapabilities: AcpAgentCapabilities;
}

/** The session's posture as the operator's machine set it. Reported, never set, over ACP. */
export interface AcpPosture {
  mode: "auto" | "review" | "read-only";
  sandbox: string;
  trusted: boolean;
  read_only: boolean;
}

/** Client-supplied MCP servers that were not connected: how many, and the sanitised names of the first of them. */
export interface AcpMcpServersIgnored {
  count: number;
  names: string[];
}

/** Conversation entries replayed on load, and how many the session holds. */
export interface AcpHistoryExtent {
  sent: number;
  total: number;
}

export interface AcpSessionMeta {
  [ACP_META_POSTURE]?: AcpPosture;
  [ACP_META_MCP_SERVERS_IGNORED]?: AcpMcpServersIgnored;
  [ACP_META_HISTORY]?: AcpHistoryExtent;
}

export interface AcpNewSessionResult {
  sessionId: string;
  _meta?: AcpSessionMeta;
}

/** The specification's `session/load` response is an empty object; Nexus's own data is under `_meta`. */
export interface AcpLoadSessionResult {
  _meta?: AcpSessionMeta;
}

/** `refusal` exists in the specification and is never sent: a gate denial is a failed tool call inside a turn that continues. */
export type AcpStopReason = "end_turn" | "cancelled" | "max_tokens" | "max_turn_requests";

/** One verifier run of the turn. */
export interface AcpVerifierRun {
  command: string;
  phase: "before_change" | "completion";
  passed: boolean;
}

export interface AcpVerifier {
  status: VerificationStatus;
  command?: string;
  source?: "configured" | "discovered";
  exit_success?: boolean;
  output_sha256?: string;
  candidate?: string;
}

/** The validation receipt of an authoritative verifier run, as the receipt's "Validation receipt" section shows it. */
export interface AcpValidationReceipt {
  id: string;
  status: string;
  candidate: string | null;
}

/**
 * What Nexus can demonstrate about a turn. `end_turn` says nothing about verification; this object does.
 * `receipt_id`: the validation receipt id when one is active, else `turn:<sessionId>:<turnId>`. `turn_id` is null only
 * for the last outcome of a loaded session, whose turn id the session record does not carry.
 */
export interface AcpVerification {
  receipt_id: string;
  turn_id: string | null;
  execution: ExecutionState;
  outcome: EngineeringOutcome;
  reason?: TurnReason;
  unverified_changes_pending: boolean;
  verifier: AcpVerifier | null;
  verifier_runs: AcpVerifierRun[];
  validation_receipt: AcpValidationReceipt | null;
}

export interface AcpVerificationMeta {
  [ACP_META_VERIFICATION]: AcpVerification;
}

export interface AcpPromptResult {
  stopReason: AcpStopReason;
  _meta?: AcpVerificationMeta;
}

/** Result of `_nexus/receipt/get`. Nexus's own type, not part of the specification. Kept in memory for the process only. */
export interface NexusReceipt {
  receipt_id: string;
  session_id: string;
  turn_id: string | null;
  verification: AcpVerification;
  sections: ReceiptSection[];
}

/** Receipt of a workspace verification requested over ACP. Its result is the existing `nexus verify` v3 document. */
export interface NexusVerificationReceipt {
  receipt_id: string;
  receipt_sha256: string;
  issued_at: string;
  surface: "acp";
  session_id: string;
  workspace: string;
  base_pinned_at: string;
  result: VerifyJsonResult;
}

/** Small result returned from `_nexus/verify`; the full verification result lives in its receipt. */
export interface NexusVerifyResult {
  service_version: number;
  receipt_id: string;
  receipt_uri: string;
  receipt_sha256: string;
  verify_schema_version: number;
  verdict: VerifyJsonResult["verdict"];
  outcome: VerifyJsonResult["outcome"];
  reason?: VerifyJsonResult["reason"];
  detail?: string;
  base?: { commit: string | null; tree: string };
  head?: { tree: string; workingTree: boolean };
  verifier?: { command: string; source: string; approval: string; digest: string };
  operator_hint?: string;
  issued_at: string;
  /** What was verified: the canonical path of the session's directory, as in the receipt. */
  workspace: string;
  /** The commit the change was measured from, and when this process pinned it for the workspace. */
  base_pinned_commit: string;
  base_pinned_at: string;
}

/** Details of an error, in the standard `data` member (`_meta` is not allowed on a JSON-RPC error). */
export interface AcpErrorData {
  /** The parameter that failed validation (-32602). */
  field?: string;
  /** A stable word for the cause, for example a sidecar error code or `sidecar_start_failed`. */
  reason?: string;
  exit_code?: number | null;
  message?: string;
}

export interface AcpError {
  code: AcpErrorCode;
  message: string;
  data?: AcpErrorData;
}

export interface AcpResultResponse {
  jsonrpc: "2.0";
  id: AcpId;
  result: AcpInitializeResult | AcpNewSessionResult | AcpLoadSessionResult | AcpPromptResult | NexusReceipt | NexusVerificationReceipt | NexusVerifyResult;
}

/** `id` is null when the request's id could not be read (not JSON, too deep, too long, a batch). */
export interface AcpErrorResponse {
  jsonrpc: "2.0";
  id: AcpId | null;
  error: AcpError;
}

export interface AcpTextContent {
  type: "text";
  text: string;
}

export interface AcpAgentMessageChunk {
  sessionUpdate: "agent_message_chunk";
  content: AcpTextContent;
}

/** Sent only while replaying a loaded session. */
export interface AcpUserMessageChunk {
  sessionUpdate: "user_message_chunk";
  content: AcpTextContent;
}

/** The tool kinds of the specification that Nexus uses; `move` and `switch_mode` exist there and no Nexus tool is one. */
export type AcpToolKind = "read" | "edit" | "delete" | "search" | "execute" | "think" | "fetch" | "other";
export type AcpToolStatus = "pending" | "in_progress" | "completed" | "failed";

export interface AcpToolTextContent {
  type: "content";
  content: AcpTextContent;
}

/** What Nexus knows about a diff beyond its text. `truncated`: the blocks come from a bounded preview or a cut diff. */
export interface AcpDiffInfo {
  kind: "added" | "modified" | "deleted";
  added: number;
  removed: number;
  truncated: boolean;
}

/** `path` is absolute. `oldText` is null for a new file. One block per hunk: the text is the hunk's lines, not the whole file. */
export interface AcpToolDiffContent {
  type: "diff";
  path: string;
  oldText: string | null;
  newText: string;
}

export type AcpToolCallContent = AcpToolTextContent | AcpToolDiffContent;

/** The tool's name and subject as the sidecar reported them (already redacted and bounded). */
export interface AcpToolRawInput {
  tool: string;
  subject: string;
}

export interface AcpToolRawOutput {
  exit_code?: number | null;
  duration_ms?: number;
  timed_out?: boolean;
  /** The operator declined the call at its approval prompt; it did not run. */
  denied?: boolean;
}

export interface AcpToolCall {
  sessionUpdate: "tool_call";
  toolCallId: string;
  title: string;
  kind: AcpToolKind;
  status: AcpToolStatus;
  rawInput?: AcpToolRawInput;
}

export interface AcpToolCallUpdateMeta {
  [ACP_META_DIFF]?: AcpDiffInfo;
}

export interface AcpToolCallUpdate {
  sessionUpdate: "tool_call_update";
  toolCallId: string;
  status?: AcpToolStatus;
  content?: AcpToolCallContent[];
  rawOutput?: AcpToolRawOutput;
  _meta?: AcpToolCallUpdateMeta;
}

/** The verification carrier: no field of its own, the object under `_meta`. */
export interface AcpSessionInfoUpdate {
  sessionUpdate: typeof ACP_VERIFICATION_CARRIER;
  _meta: AcpVerificationMeta;
}

export type AcpSessionUpdate = AcpAgentMessageChunk | AcpUserMessageChunk | AcpToolCall | AcpToolCallUpdate | AcpSessionInfoUpdate;

export interface AcpSessionUpdateNotification {
  jsonrpc: "2.0";
  method: "session/update";
  params: { sessionId: string; update: AcpSessionUpdate };
}

export interface AcpPermissionOption {
  optionId: typeof ACP_ALLOW_ONCE_OPTION_ID | typeof ACP_REJECT_ONCE_OPTION_ID;
  name: string;
  kind: "allow_once" | "reject_once";
}

export interface AcpPermissionToolCallMeta {
  /** SHA-256 of the canonical `{tool, subject, preview, review}` of the approval this request asks about. */
  [ACP_META_APPROVAL_DIGEST]: string;
}

export interface AcpPermissionToolCall {
  toolCallId: string;
  title: string;
  kind: AcpToolKind;
  status: "pending";
  content: AcpToolCallContent[];
  rawInput: AcpToolRawInput;
  _meta: AcpPermissionToolCallMeta;
}

/** `id` is an integer from a random start, so a reply sent before the request exists matches nothing. */
export interface AcpPermissionRequest {
  jsonrpc: "2.0";
  id: number;
  method: "session/request_permission";
  params: { sessionId: string; toolCall: AcpPermissionToolCall; options: AcpPermissionOption[] };
}

/** Everything Nexus sends. It calls no other client method. */
export type AcpAgentMessage = AcpResultResponse | AcpErrorResponse | AcpSessionUpdateNotification | AcpPermissionRequest;

/** One line of the connection, in either direction: the root of the published schema. */
export type AcpAdapterDocument = AcpClientMessage | AcpAgentMessage;

/** The exactly two options of every permission request. */
export const ACP_PERMISSION_OPTIONS: readonly AcpPermissionOption[] = [
  { optionId: ACP_ALLOW_ONCE_OPTION_ID, name: "Allow once", kind: "allow_once" },
  { optionId: ACP_REJECT_ONCE_OPTION_ID, name: "Reject", kind: "reject_once" },
];
